/// <summary>
///     The <c>AVASalesOrderCopyingContractCls_Extension</c> class is the extension for <c>SalesOrderCopyingContract</c>
/// </summary>
[ExtensionOf(classStr(SalesOrderCopyingContract))]
final class AVASalesOrderCopyingContractCls_Extension
{
    public boolean clsAVACalcSalesLine;
    public boolean clsAVASalesOrderCreditNote;
    public boolean clsAVASalesOrderCreditNoteSingle;
    public boolean clsAVASalesOrderSearch;

    #define.CurrentVersion(1)

    #localmacro.AVACurrentList
        clsAVACalcSalesLine,
        clsAVASalesOrderCreditNote,
        clsAVASalesOrderCreditNoteSingle,
        clsAVASalesOrderSearch
    #endmacro

}

