/// <summary>
///     AVA <c>pack</c> method.
/// </summary>
/// <returns>
///     <c>container</c> as return value
/// </returns>
public container pack()
{
    return [#CurrentVersion, #AVACurrentList] + [next pack()];
}

/// <summary>
///     AVA <c>unpack</c> method.
/// </summary>
/// <param name="_packedClass">
///     <c>container</c> as type
/// </param>
/// <returns>
///     <c>boolean</c> as return value
/// </returns>
public boolean unpack(container _packedClass)
{
    boolean     retVal;

    int         version;
    container   base;

    version = RunBase::getVersion(_packedClass);
    /*
    switch (version)
    {
        case #CurrentVersion:
            [version, #AVACurrentList, base] = _packedClass;
            //return next unpack(base);
        default :
            return false;
    }
    */
    [version, #AVACurrentList, base] = _packedClass;

    retVal = next unpack(base);

    return retVal;
}

